#!/usr/bin/env python3
"""Regenerates egg-phreox-service.json. The egg embeds install.sh, so edit that and run this script."""
import json
from pathlib import Path

here = Path(__file__).parent
script = (here / "install.sh").read_text()


def variable(name, description, env, default, rules, viewable=True):
    return {"name": name, "description": description, "env_variable": env, "default_value": default,
            "user_viewable": viewable, "user_editable": True, "rules": rules, "field_type": "text"}


egg = {
    "_comment": "DO NOT EDIT: FILE GENERATED BY pterodactyl/build-egg.py",
    "meta": {"version": "PTDL_v2", "update_url": None},
    "exported_at": "2026-11-06T00:00:00+00:00",
    "name": "Phreox Service",
    "author": "admin@bluenet-hosting.com",
    "description": "phreox-service, the account, friends, DM and presence server of Phreox. A supervisor checks the releases repository "
                   "every 30 seconds and updates the server without a gap: the new version listens next to the old one on the same port, "
                   "then the old one finishes its requests and stops.",
    "features": None,
    "docker_images": {"Java 25": "ghcr.io/pterodactyl/yolks:java_25"},
    "file_denylist": [],
    # The supervisor only waits and asks GitHub: it gets a tiny JVM of its own, the service a small one (see PHREOX_JAVA_OPTS).
    "startup": "java -XX:+UseSerialGC -Xms8m -Xmx32m -Xss256k -XX:TieredStopAtLevel=1 -XX:CICompilerCount=1 -XX:-UsePerfData -XX:ReservedCodeCacheSize=16m -XX:MaxMetaspaceSize=64m -cp supervisor.jar talk.phreox.service.supervisor.Supervisor",
    "config": {"files": "{}", "startup": json.dumps({"done": "Phreox supervisor: service is up"}), "logs": "{}", "stop": "^C"},
    "scripts": {"installation": {"script": script, "container": "ghcr.io/ptero-eggs/installers:debian", "entrypoint": "bash"}},
    "variables": [
        variable("Update channel", "Which releases this server follows: release (stable), beta (beta, pre, rc), alpha or dev. The server only takes releases of its own channel.",
                 "PHREOX_UPDATE_CHANNEL", "release", "required|string|in:release,beta,alpha,dev"),
        variable("Releases repository", "GitHub repository the releases are published to.",
                 "PHREOX_UPDATE_REPO", "Phreox/releases", "required|string|regex:/^[A-Za-z0-9_.-]+\\/[A-Za-z0-9_.-]+$/"),
        variable("GitHub token", "Token with read access to the contents of the releases repository. Needed while that repository is private.",
                 "PHREOX_UPDATE_TOKEN", "", "nullable|string|max:255", False),
        variable("Update interval (seconds)", "How often the releases are checked. A check that finds nothing new costs no API quota.",
                 "PHREOX_UPDATE_INTERVAL_SECONDS", "30", "required|integer|between:5,3600"),
        variable("Admin token", "Secret of the operator, at least 32 characters. Only a node that presents it may use a reserved domain, and entitlements can only be granted with it.",
                 "PHREOX_SERVICE_ADMIN_TOKEN", "", "nullable|string|min:32|max:255", False),
        variable("Reserved domains", "Comma separated domains that ordinary accounts cannot register nodes for.",
                 "PHREOX_SERVICE_RESERVED_DOMAINS", "phreox.talk", "nullable|string|max:255"),
        variable("Klipy key", "Klipy app key for the GIF search. Without it the service offers no GIFs.",
                 "PHREOX_KLIPY_KEY", "", "nullable|string|max:255", False),
        variable("Java options", "Options of the JVM that runs the service. The default keeps it small: serial collector, 192 MB heap at most, one compiler thread.",
                 "PHREOX_JAVA_OPTS", "-XX:+UseSerialGC -Xms16m -Xmx192m -Xss256k -XX:MaxMetaspaceSize=96m -XX:ReservedCodeCacheSize=24m -XX:TieredStopAtLevel=1 -XX:CICompilerCount=1 -XX:-UsePerfData -XX:+ExitOnOutOfMemoryError", "required|string|max:255"),
    ],
}

(here / "egg-phreox-service.json").write_text(json.dumps(egg, indent=2, ensure_ascii=False) + "\n")
print("egg-phreox-service.json:", len(egg["variables"]), "variables")
